<?php
namespace App\Controllers;

use App\Core\{CSRF,Database,Audit,View,Authorization,TenantContext,HttpException};
use App\Services\ModuleService;

final class CustomerController
{
    public function index():void
    {
        Authorization::require('customers.view');$t=TenantContext::id();$pdo=Database::connection();$behavior=ModuleService::has('behavior',$t);
        $sql=$behavior?"SELECT c.*,bp.avg_interval_days,bp.next_expected_date,bp.confidence_score FROM customers c LEFT JOIN behavior_profiles bp ON bp.customer_id=c.id AND bp.tenant_id=c.tenant_id WHERE c.tenant_id=:t ORDER BY c.status='active' DESC,c.created_at DESC LIMIT 500":"SELECT c.*,NULL avg_interval_days,NULL next_expected_date,NULL confidence_score FROM customers c WHERE c.tenant_id=:t ORDER BY c.status='active' DESC,c.created_at DESC LIMIT 500";$q=$pdo->prepare($sql);$q->execute(['t'=>$t]);View::render('customers/index',['title'=>'Clientes','customers'=>$q->fetchAll(),'behaviorEnabled'=>$behavior]);
    }
    public function show(string $id):void
    {
        Authorization::require('customers.view');$t=TenantContext::id();$cid=(int)$id;$pdo=Database::connection();$q=$pdo->prepare('SELECT c.*,bp.avg_interval_days,bp.next_expected_date,bp.confidence_score,bp.visits_count FROM customers c LEFT JOIN behavior_profiles bp ON bp.customer_id=c.id AND bp.tenant_id=c.tenant_id WHERE c.id=:id AND c.tenant_id=:t');$q->execute(['id'=>$cid,'t'=>$t]);$customer=$q->fetch();if(!$customer)HttpException::abort(404,'Cliente não encontrado.');$q=$pdo->prepare("SELECT a.*,s.name service_name,p.name professional_name,v.model vehicle_model,v.plate vehicle_plate FROM appointments a JOIN services s ON s.id=a.service_id LEFT JOIN professionals p ON p.id=a.professional_id LEFT JOIN customer_vehicles v ON v.id=a.vehicle_id WHERE a.tenant_id=:t AND a.customer_id=:c ORDER BY a.starts_at DESC LIMIT 100");$q->execute(['t'=>$t,'c'=>$cid]);$appointments=$q->fetchAll();$q=$pdo->prepare("SELECT sa.*,p.name professional_name FROM sales sa LEFT JOIN professionals p ON p.id=sa.professional_id WHERE sa.tenant_id=:t AND sa.customer_id=:c ORDER BY sa.created_at DESC LIMIT 100");$q->execute(['t'=>$t,'c'=>$cid]);$sales=$q->fetchAll();$spentServices=0;$completedVisits=0;$cancelled=0;$noShow=0;$lastVisit=null;foreach($appointments as $a){if($a['status']==='completed'){$spentServices+=(float)$a['service_price_snapshot'];$completedVisits++;if($lastVisit===null)$lastVisit=$a['starts_at'];}elseif($a['status']==='cancelled')$cancelled++;elseif($a['status']==='no_show')$noShow++;}$spentProducts=0;foreach($sales as $s)if($s['status']==='completed')$spentProducts+=(float)$s['total'];$avgTicket=$completedVisits>0?($spentServices+$spentProducts)/$completedVisits:0.0;$favoriteService=null;$favoriteProfessional=null;$fq=$pdo->prepare("SELECT s.name,COUNT(*) total FROM appointments a JOIN services s ON s.id=a.service_id WHERE a.tenant_id=:t AND a.customer_id=:c AND a.status='completed' GROUP BY s.id,s.name ORDER BY total DESC,MAX(a.starts_at) DESC LIMIT 1");$fq->execute(['t'=>$t,'c'=>$cid]);$favoriteService=$fq->fetch()?:null;$fq=$pdo->prepare("SELECT p.name,COUNT(*) total FROM appointments a JOIN professionals p ON p.id=a.professional_id WHERE a.tenant_id=:t AND a.customer_id=:c AND a.status='completed' GROUP BY p.id,p.name ORDER BY total DESC,MAX(a.starts_at) DESC LIMIT 1");$fq->execute(['t'=>$t,'c'=>$cid]);$favoriteProfessional=$fq->fetch()?:null;$insights=['completed_visits'=>$completedVisits,'cancelled'=>$cancelled,'no_show'=>$noShow,'last_visit'=>$lastVisit,'avg_ticket'=>$avgTicket,'favorite_service'=>$favoriteService,'favorite_professional'=>$favoriteProfessional];$vehicles=[];$q=$pdo->prepare('SELECT * FROM customer_vehicles WHERE tenant_id=:t AND customer_id=:c AND active=1 ORDER BY model');$q->execute(['t'=>$t,'c'=>$cid]);$vehicles=$q->fetchAll();$loyalty=0;if(ModuleService::has('loyalty',$t)){$q=$pdo->prepare('SELECT points FROM loyalty_accounts WHERE tenant_id=:t AND customer_id=:c');$q->execute(['t'=>$t,'c'=>$cid]);$loyalty=(int)$q->fetchColumn();}$packages=[];if(ModuleService::has('packages',$t)){$q=$pdo->prepare('SELECT cp.*,sp.name package_name FROM customer_packages cp JOIN service_packages sp ON sp.id=cp.package_id WHERE cp.tenant_id=:t AND cp.customer_id=:c ORDER BY cp.id DESC');$q->execute(['t'=>$t,'c'=>$cid]);$packages=$q->fetchAll();}View::render('customers/show',['title'=>$customer['name'],'customer'=>$customer,'appointments'=>$appointments,'sales'=>$sales,'vehicles'=>$vehicles,'loyalty'=>$loyalty,'packages'=>$packages,'spentServices'=>$spentServices,'spentProducts'=>$spentProducts,'behaviorEnabled'=>ModuleService::has('behavior',$t),'packagesEnabled'=>ModuleService::has('packages',$t),'loyaltyEnabled'=>ModuleService::has('loyalty',$t),'insights'=>$insights]);
    }
    public function create():void{Authorization::require('customers.create');TenantContext::id();View::render('customers/form',['title'=>'Novo cliente','customer'=>null]);}
    public function store():void{Authorization::require('customers.create');CSRF::enforce();$d=$this->validated();$pdo=Database::connection();$t=TenantContext::id();$pdo->prepare("INSERT INTO customers(tenant_id,name,phone,email,birth_date,consent_marketing,status,created_at,updated_at)VALUES(:t,:name,:phone,:email,:birth,:consent,'active',NOW(),NOW())")->execute(['t'=>$t]+$d);$id=(int)$pdo->lastInsertId();Audit::log('customer.create','customers',$id,null,['name'=>$d['name']]);header('Location: /customers/'.$id);exit;}
    public function edit(string $id):void{Authorization::require('customers.edit');$q=Database::connection()->prepare('SELECT * FROM customers WHERE id=:id AND tenant_id=:t');$q->execute(['id'=>(int)$id,'t'=>TenantContext::id()]);$c=$q->fetch();if(!$c)HttpException::abort(404,'Cliente não encontrado.');View::render('customers/form',['title'=>'Editar cliente','customer'=>$c]);}
    public function update(string $id):void{Authorization::require('customers.edit');CSRF::enforce();$t=TenantContext::id();$cid=(int)$id;$pdo=Database::connection();$q=$pdo->prepare('SELECT * FROM customers WHERE id=:id AND tenant_id=:t');$q->execute(['id'=>$cid,'t'=>$t]);$old=$q->fetch();if(!$old)HttpException::abort(404,'Cliente não encontrado.');$d=$this->validated();$status=in_array($_POST['status']??'active',['active','inactive','blocked'],true)?(string)$_POST['status']:'active';$pdo->prepare('UPDATE customers SET name=:name,phone=:phone,email=:email,birth_date=:birth,consent_marketing=:consent,status=:status,updated_at=NOW() WHERE id=:id AND tenant_id=:t')->execute($d+['status'=>$status,'id'=>$cid,'t'=>$t]);Audit::log('customer.update','customers',$cid,$old,['name'=>$d['name'],'status'=>$status]);header('Location: /customers/'.$cid);exit;}
    public function deactivate(string $id):void{Authorization::require('customers.edit');CSRF::enforce();$t=TenantContext::id();$q=Database::connection()->prepare("UPDATE customers SET status='inactive',updated_at=NOW() WHERE id=:id AND tenant_id=:t");$q->execute(['id'=>(int)$id,'t'=>$t]);if(!$q->rowCount())HttpException::abort(404,'Cliente não encontrado.');Audit::log('customer.deactivate','customers',(int)$id);header('Location: /customers');exit;}
    private function validated():array{$name=trim((string)($_POST['name']??''));$phone=preg_replace('/\D+/','',(string)($_POST['phone']??''));$email=mb_strtolower(trim((string)($_POST['email']??'')));$birth=trim((string)($_POST['birth_date']??''));if(strlen($name)<2||strlen($name)>150||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||($birth!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$birth)))HttpException::abort(422,'Dados do cliente inválidos.');return ['name'=>$name,'phone'=>$phone?:null,'email'=>$email?:null,'birth'=>$birth?:null,'consent'=>isset($_POST['consent_marketing'])?1:0];}
}
